[workspace]
members = ["crates/aptu-coder-core", "crates/aptu-coder"]
exclude = ["fuzz"]
resolver = "2"

[workspace.package]
version = "0.47.0"
edition = "2024"
rust-version = "1.98.0"
authors = ["Hugues Clouatre"]
license = "Apache-2.0"
repository = "https://github.com/clouatre-labs/aptu-coder"
homepage = "https://github.com/clouatre-labs/aptu-coder"

[workspace.dependencies]
tree-sitter = "0.27.1"
rayon = "1"
ignore = "0.4"
lru = "0.19"
blake3 = "1"
snap = "1"
serde = { version = "1", features = ["derive"] }
serde_json = "1"
base64 = "0.23"
thiserror = "2.0.21"
tracing = "0.1"
tokio-util = "0.7"
rmcp = { version = "3", features = ["server", "macros", "transport-io", "transport-streamable-http-server"] }
